"""Validate, review and WebP-encode the images generated by YUMEI ComfyUI.

Pillow is used only for lossless inspection, review-sheet layout and web encoding;
all creative image generation stays in the project's ComfyUI workflow.
"""
import argparse
import hashlib
import json
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont, ImageStat

ROOT = Path(__file__).resolve().parents[1]
STAGING = ROOT / "output/creator/generated-v2"
parser = argparse.ArgumentParser()
parser.add_argument("--publish", action="store_true")
args = parser.parse_args()
manifest = json.loads((STAGING / "manifest.json").read_text(encoding="utf-8"))
jobs = manifest["jobs"]
groups = {}
hashes = set()
for job in jobs:
    if job["status"] != "generated":
        continue
    raw = STAGING / "raw" / Path(job["source"]).with_suffix(".png")
    with Image.open(raw) as original:
        original.load()
        if original.size != (512, 800):
            raise ValueError(f"Unexpected dimensions: {job['id']} {original.size}")
        picture = original.convert("RGB")
    digest = hashlib.sha256(raw.read_bytes()).hexdigest()
    if digest != job["hash"] or digest in hashes:
        raise ValueError(f"Corrupted or duplicate output: {job['id']}")
    hashes.add(digest)
    if max(ImageStat.Stat(picture).stddev) < 12:
        raise ValueError(f"Nearly blank output: {job['id']}")
    group = f"{job['gender']}/{job['style']}/{job['category']}"
    groups.setdefault(group, []).append((job, picture))

review = STAGING / "review"
review.mkdir(exist_ok=True)
font_path = Path("C:/Windows/Fonts/arial.ttf")
font = ImageFont.truetype(str(font_path), 16) if font_path.exists() else ImageFont.load_default()
small = ImageFont.truetype(str(font_path), 13) if font_path.exists() else ImageFont.load_default()
for group, images in groups.items():
    columns = min(5, len(images))
    rows = (len(images) + columns - 1) // columns
    sheet = Image.new("RGB", (columns * 172 + 16, rows * 286 + 52), "#f4f1ee")
    draw = ImageDraw.Draw(sheet)
    draw.text((12, 12), group, font=font, fill="#222222")
    for index, (job, picture) in enumerate(images):
        x, y = 8 + (index % columns) * 172, 44 + (index // columns) * 286
        thumbnail = picture.copy()
        thumbnail.thumbnail((160, 250), Image.Resampling.LANCZOS)
        sheet.paste(thumbnail, (x, y))
        draw.text((x, y + 254), job["option"], font=small, fill="#222222")
    sheet.save(review / f"{group.replace('/', '-')}.jpg", quality=92)
print(f"Validated and reviewed {len(hashes)}/{len(jobs)} generated images")

if args.publish:
    if len(hashes) != len(jobs) or len(jobs) != 124:
        raise ValueError("All 124 images must be generated before publishing")
    destination = ROOT / "client/public/character-options/creator"
    total = 0
    for job in jobs:
        raw = STAGING / "raw" / Path(job["source"]).with_suffix(".png")
        output = destination / job["source"]
        if not output.resolve().is_relative_to(destination.resolve()):
            raise ValueError("Output outside the creator asset directory")
        output.parent.mkdir(parents=True, exist_ok=True)
        with Image.open(raw) as picture:
            picture.convert("RGB").save(output, "WEBP", quality=88, method=6)
        total += output.stat().st_size
        job["webpSha256"] = hashlib.sha256(output.read_bytes()).hexdigest()
        job["webpBytes"] = output.stat().st_size
    audit = ROOT / "docs/creator-assets-v2.json"
    audit.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Published {len(jobs)} WebP images ({total:,} bytes)")
